curl -s -X POST https://slack.com/api/conversations.list -H "Content-Type: application/json" -d '{"token":"***","types":"public_channel","exclude_archived":true}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR:',d); sys.exit(1)
for c in d['channels']:
    if c.get('name')=='feedback':
        print(c['id'], c.get('name'))
"

