arguments.command:
python3 -c "
import json
d=json.load(open('/tmp/feedback_history.json'))
for m in d['messages']:
    if m.get('reactions') is not None:
        print(m['ts'], m['user'], m.get('text','')[:60].replace(chr(10),' | '))
        for r in m['reactions']:
            print('  ', r['name'], r['users'])
    else:
        print('no reactions:', m['ts'], m['user'])
"

